/**
 * The Supabase client, loaded from a CDN so the app stays buildless.
 * js/env.js is git-ignored locally and generated by the deploy workflow.
 */
import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.4/+esm';
import { t } from './i18n.js';

let ENV = {};
try {
  ({ ENV } = await import('./env.js'));
} catch { /* not configured yet: handled by `configured` */ }

export const configured = Boolean(
  ENV?.supabaseUrl && ENV?.supabaseAnonKey && !ENV.supabaseUrl.includes('YOUR-PROJECT-REF'));

export const sb = configured
  ? createClient(ENV.supabaseUrl, ENV.supabaseAnonKey, {
      auth: { persistSession: true, autoRefreshToken: true, storageKey: 'pq.auth' }
    })
  : null;

/** supabase-js can occasionally hang on its session lock; never wait for ever. */
export const withTimeout = (promise, ms = 10000) => Promise.race([
  promise,
  new Promise((_, reject) => setTimeout(() => reject(new Error('timed out')), ms))
]);

/** A sentence a person can act on, in the current language. Never empty. */
export function errorMessage(error) {
  if (!navigator.onLine) return t('err.offline');
  const raw = error?.message || '';
  const map = [
    [/Failed to fetch|NetworkError|fetch failed|timed out/i, 'err.network'],
    [/Invalid login credentials/i,                           'err.login'],
    [/JWT|token is expired/i,                                'err.session'],
    [/row-level security|permission denied|42501/i,          'err.permission']
  ];
  const hit = map.find(([re]) => re.test(raw) || re.test(error?.code ?? ''));
  return hit ? t(hit[1]) : raw || t('err.generic');
}
